def integrate(function, a, b, epsabs, epsrel, limit, key):
    func = GSLFunction(function)
    ws = GSLIntegrationWorkspace()

    status = gsl.gsl_integration_qag(func, a, b, epsabs, epsrel, limit, key, ws)

    if status != 0:
        raise RuntimeError("Integration failed with status {}".format(status))

    return ws.result, ws.error

