# GSL Matrix class
class GSLMatrix(object):
    def __init__(self, rows, cols):
        self.rows = rows
        self.cols = cols
        self._allocate()

    def _allocate(self):
        gsl.gsl_matrix_alloc(ctypes.byref(self.gsl_matrix), self.rows, self.cols)

    def free(self):
        gsl.gsl_matrix_free(self.gsl_matrix)

    def to_numpy(self):
        return np.array(gsl.gsl_matrix_get_data(self.gsl_matrix)).reshape((self.rows, self.cols))

# Function to convert a list to a GSL matrix
def list_to_ctypes_matrix(lst):
    rows, cols = len(lst), len(lst[0])
    gsl_matrix = GSLMatrix(rows, cols)
    for i in range(rows):
        for j in range(cols):
            gsl.gsl_matrix_set(gsl_matrix.gsl_matrix, i, j, lst[i][j])
    return gsl_matrix

# Function to compute the covariance matrix
def compute_covariance(jacobian, epsrel):
    gsl_matrix_jac = list_to_ctypes_matrix(jacobian)
    covariance = GSLMatrix(jacobian[0], jacobian[0])
    gsl.gsl_multifit_nlinear_covar(gsl_matrix_jac.gsl_matrix, epsrel, covariance.gsl_matrix)
    return covariance.to_numpy()

