class GSLMatrix(ctypes.Structure):
    _fields_ = [("nrows", ctypes.c_int), ("ncols", ctypes.c_int), ("data", ctypes.POINTER(ctypes.c_double))]

def is_positive_definite(matrix):
    gsl.gsl_matrix_view_array(matrix, True)
    status = gsl.gsl_linalg_cholesky_is_pd()
    gsl.gsl_matrix_view_array(matrix, False)
    return status == 0

def cholesky_decomp(matrix):
    gsl.gsl_matrix_view_array(matrix, True)
    cholesky = gsl.gsl_linalg_cholesky_alloc()
    status = gsl.gsl_linalg_cholesky_decomp(cholesky, matrix)
    gsl.gsl_matrix_view_array(matrix, False)

    if status != 0:
        raise ValueError("Matrix is not positive definite.")

    lower_triangular_matrix = [[matrix[i][j] for j in range(i + 1)] for i in range(matrix.shape[0])]
    gsl.gsl_linalg_cholesky_free(cholesky)
    return lower_triangular_matrix

def perform_cholesky_decomposition(matrix):
    if len(matrix) != len(matrix[0]):
        raise ValueError("Input matrix must be square.")

    gsl.gsl_matrix_init(len(matrix), len(matrix))

    for i in range(len(matrix)):
        for j in range(len(matrix)):
            gsl.gsl_matrix_set(matrix, i, j, matrix[i][j])

    if is_positive_definite(matrix):
        lower_triangular_matrix = cholesky_decomp(matrix)
        return json.dumps({"Candidate_solution": str(lower_triangular_matrix)})
    else:
        raise ValueError("Matrix is not positive definite.")

