typedef void (*compare_func)(void*, const void*, const void*);
\

\
int compare_ascending(const void* a, const void* b)
\
{
\
    double x = *((double*)a);
\
    double y = *((double*)b);
\
    return x < y ? -1 : x > y ? 1 : 0;
\
}
\

\
int* gsl_heapsort_index(double* data, size_t size, compare_func compare)
\
{
\
    int* indices = malloc(sizeof(int) * size);

\
    for (size_t i = 0; i < size; i++) { indices[i] = i; }

\
    gsl_sort_index(indices, size, compare, data);

\
    return indices;
\
}

