int main()
\
{
\
    double data[] = {4.0, 1.0, 3.0, 2.0};
\
    size_t size = sizeof(data) / sizeof(double);

\
    compare_func compare = compare_ascending;

\
    int* indices = gsl_heapsort_index(data, size, compare);

\
    assert(indices[0] == 1);

\
    assert(indices[1] == 3);

\
    assert(indices[2] == 2);

\
    assert(indices[3] == 0);

\
    free(indices);

\
    return 0;
